/* Routing geometry, generated by Bolt Bench — overwritten on export. */
#pragma once
#include <Arduino.h>

#define NUM_LEDS     300

#define SEG_NAME_LEN 20       // fixed array, so memcpy_P hands back a usable string

struct Segment {
  char     name[SEG_NAME_LEN];   // ASCII; folded from the bench's run names
  uint16_t start;
  uint16_t len;
  uint8_t  isBolt;
  uint8_t  ox, oy;      // channel root, normalised 0..255
  int8_t   parent;      // -1 = root channel; otherwise the channel it forks off
  uint8_t  forkAt;      // 0..255 along the parent, where the branch leaves
};

#define SEG_CLOUD_BODY_0       0
#define SEG_BOLT_LEFT_1        1
#define SEG_FORK_LEFT_2        2
#define SEG_BOLT_CENTRE_3      3
#define SEG_FORK_CENTRE_4      4
#define SEG_BOLT_RIGHT_5       5
#define SEG_FORK_RIGHT_6       6
#define NUM_SEGMENTS 7

